namespace SchoolERP.Api.Logging;public interface ILogRedactor{object? RedactValue(string key,object? value);string RedactEmail(string? value);string RedactPhone(string? value);}public sealed class LogRedactor:ILogRedactor{private static readonly string[] Sensitive=["password","token","authorization","cookie","secret","signingkey","apikey","connectionstring"];public object? RedactValue(string key,object? value)=>Sensitive.Any(x=>key.Contains(x,StringComparison.OrdinalIgnoreCase))?"[REDACTED]":value;public string RedactEmail(string? value){if(string.IsNullOrWhiteSpace(value))return "[REDACTED]";var at=value.IndexOf('@');return at<=0?"[REDACTED]":value[0]+"***"+value[at..];}public string RedactPhone(string? value){if(string.IsNullOrWhiteSpace(value))return "[REDACTED]";var digits=new string(value.Where(char.IsDigit).ToArray());return digits.Length<=4?"***":"***"+digits[^4..];}}
